const additions={
 'gidai/kaledines-dovanos':[
  H('Daiktas, veikla ar jau sukurtas prisiminimas?'),
  P('Šie trys dovanos formatai sprendžia skirtingus norus. Daiktas praverčia, kai žinote konkrečią jo vietą gavėjo kasdienybėje. Veikla dovanoja progą ką nors patirti, todėl svarbus dalyvavimas ir laikas. Jau paruoštas prisiminimas, pavyzdžiui, jūsų užpildytas albumas, labiau priklauso nuo darbo, kurį atlikote prieš įteikimą. Nesirinkite vien pagal gražiausią dėžutę: apsispręskite, ką žmogus galės padaryti su dovana ją atidaręs.'),
  L('Daiktas: įteikiate jo norėtą konkretų modelį ir reikalingą naudojimo informaciją. Pavyzdys – su turima virykle suderinamas kavinukas.','Veikla: įteikiate priemones arba čekį ir aiškų, tačiau lankstų dalyvavimo planą. Pavyzdys – abiejų norimas kūrybos vakaras.','Prisiminimas: įteikiate užbaigtą turinį. Pavyzdys – atrinktos nuotraukos su vardais, datomis ir trumpomis istorijomis, o ne vien tuščias albumas.'),
  H('Kai dovana kuriama: įteikimo diena ir užbaigimo diena'),
  P('Kūrybinį rinkinį galite padėti po eglute neatidarytą. Tuomet gavėjai patys išsirinks veiklos dieną. Jei norite įteikti jau pagamintą rankų liejinį, procesą reikia pradėti anksčiau: susitikti, pasiruošti, suformuoti atspaudą, išlieti gipsą, išimti ir išdžiovinti darbą. Poros bei šeimos rinkinių receptuose numatytos 5–7 džiovinimo paros po išėmimo. Tai nėra bendras užsakymo gavimo ar visos dovanos pagaminimo terminas.'),
  P('Pavyzdžiui, jei iki susitikimo liko tik kelios dienos, rinkinio įteikimas su kvietimu kurti vėliau yra įgyvendinamas sumanymas. Užbaigto, nudažyto liejinio pažadas tuo pačiu laikotarpiu gali prieštarauti jo instrukcijai. Planuodami naudokitės poros rinkinio instrukcija arba šeimos rinkinio instrukcija, o siuntos gavimą patvirtinkite atskirai. Trumpas vaizdo įrašas parodo veiklos pobūdį, bet nepakeičia konkretaus recepto.'),
  H('Kaip mažą dovaną padaryti asmenišką be papildomo pirkinio?'),
  P('Prie vieno tinkamo daikto pridėkite vieną konkretų savo indėlį. Skirtukui tiks lapelis su gavėjo rekomenduota knyga ir jūsų mintimi apie ją. Albumui – jau paruošta pirmoji istorija. Kūrybiniam rinkiniui – pasiūlymas pasirūpinti darbo vieta ir po veiklos ją sutvarkyti. Asmeniškumas atsiranda iš ryšio su žmogumi, todėl įpakavimo nereikia užpildyti atsitiktiniais suvenyrais.'),
  P('Jei dovanojate per atstumą, atskirkite pačią siuntą ir jos prasmę paaiškinančią žinutę. Gavėjas turi suprasti, nuo ko dovana ir kodėl ją parinkote. Nenustatykite privalomo skambučio vien tam, kad pamatytumėte reakciją: geriau pasiūlykite vėliau susisiekti jam patogiu metu. O jeigu dovana skirta keliems žmonėms, kortelėje prisiminkite kiekvieną, užuot viską adresavę vien organizuojančiam šeimos nariui.'),
  H('Dažni klausimai apie kalėdinių dovanų pasirinkimą'),
  ...QA('Ką dovanoti žmogui, kuris nenori daiktų?','Pasiūlykite konkrečią jo norimą veiklą arba savo atliktą darbą: paruoštą nuotraukų atranką, bendrą pasivaikščiojimą, jo mėgstamo patiekalo vakarą. Pirma išgirskite, ar „nenori daiktų“ reiškia norą daugiau bendrauti, ar tiesiog prašymą apsieiti be dovanų.'),
  ...QA('Ar elektroninis kuponas išsprendžia paskutinės minutės problemą?','Jis gali išspręsti fizinės siuntos laukimą. Dar reikia patikrinti apmokėjimo įskaitymą, kupono gavimą, galiojimą, vietą ir rezervaciją. Vieną kartą patikrinkite gautą failą ir adresatą; vien užsakymo patvirtinimas nebūtinai yra pats kuponas.'),
  ...QA('Kiek dovanų geriau įteikti vienam žmogui?','Pradėkite nuo vienos aiškios minties. Jei ją užbaigia vienas daiktas ir jūsų paruošta žinutė, daugiau pirkinių nereikia. Kelių dalių rinkinys prasmingas tada, kai dalys naudojamos kartu ir visos telpa į numatytą bendrą sumą.'),
 ],
 'gidai/kaledines-dovanos-moterims':[
  H('Kaip suteikti asmeniškumo netaikant dovanos visoms vienodai?'),
  P('Pasirinkite vieną jos pasakytą norą ir vieną tikrą bendrą prisiminimą. Noras padeda parinkti pačią dovaną, o prisiminimas – paaiškinti, kodėl ji skirta būtent jai. Jei draugė kelionėje vis fotografavo senamiesčio duris, galite atrinkti jos jau turimus kadrus į nedidelę nuotraukų istoriją. Jei kolegė kalbėjo apie mėgstamą autorių, prie knygų kupono užteks nuoširdaus palinkėjimo. Santykio artumas lemia ir tai, kiek asmeninių detalių tinka naudoti.'),
  P('Graviravimas ar vardinis užrašas nėra būtina sąlyga. Prieš individualų užsakymą verta pasitikrinti rašybą, maketą ir gamybos eigą, o jei šios informacijos neturite, asmeninę žinutę galite pridėti patys. Taip asmeninę dalį galėsite pataisyti savo rankomis, nekeisdami pagrindinio daikto.'),
  H('Trys skirtingos šventinės situacijos'),
  S('Kolegė: nedidelė dovana be papildomos pareigos'),
  P('Laikykitės bendros komandos sumos, rinkitės žinomą pomėgį ir įteikite paprastai. Jei nežinote jos maisto pomėgių ar naudojamų kosmetikos priemonių, nenuspėkite jų iš bendro dovanų sąrašo. Tinka pasirinkimo laisvę paliekantis variantas, kurio panaudojimui nereikės primokėti už jums suplanuotą brangią paslaugą.'),
  S('Draugė: dalis jūsų bendros istorijos'),
  P('Paruoškite mažą, užbaigtą nuotraukų atranką: vieną kelionę, vieną tradiciją ar vieną jums abiem svarbų susitikimą. Prie kadrų parašykite po sakinį, kurį suprasite abi. Jei perkate albumą, pirmus puslapius užpildykite prieš įteikdami. Atskirai suderinkite, ar galima naudoti kitų žmonių nuotraukas; asmeniška dovana nebūtinai turi virsti viešu socialinių tinklų įrašu.'),
  S('Partnerė: jos noras ir jūsų abiejų laikas'),
  P('Bendra kūryba gali būti taiklus pasirinkimas, kai partnerė pati tokios veiklos nori. Prie rinkinio galima pridėti dvi galimas susitikimo datas ir pasiūlymą pasirūpinti priemonėmis. Renkantis rankų liejimą, atskirkite vakaro veiklą nuo vėliau užbaigiamos skulptūros. Pagal mūsų poros rinkinio instrukciją išimtas liejinys dar džiovinamas 5–7 paras; dažymas nėra to paties vakaro pažadas.'),
  H('Kai dovana bus naudojama po švenčių'),
  P('Pasirūpinkite, kad gavėja rastų aiškų kitą veiksmą: kokia parduotuvė priima kuponą, kur registruotis į veiklą arba kur padėta rinkinio instrukcija. Nepalikite vien bendros nuorodos į didelį paslaugų katalogą. Jei kartu dovanojate savo laiką, pasiūlykite po švenčių susisiekti ir susitarti, o ne iš anksto užrakinkite jai nežinomą datą.'),
  H('Klausimai renkant Kalėdų dovaną moteriai'),
  ...QA('Ką rinktis, kai jos skonis neaiškus?','Paklauskite apie dvi konkrečias kryptis, pavyzdžiui, knygas arba bendrą užsiėmimą. Atsakymas susiaurins pasirinkimą, o konkretus pirkinys ir įteikimas dar gali likti staigmena. Nežinomą skonį sunku kompensuoti vien didesne dovanos kaina.'),
  ...QA('Ar veikla dviem visada reiškia, kad dalyvaus ir dovanotojas?','Ne. Jei dovana skirta gavėjai, leiskite jai pasirinkti žmogų, su kuriuo norės dalyvauti. Pirkdami patikrinkite, ar pasirinktas pasiūlymas iš tiesų skirtas dviem ir kokios registracijos sąlygos.'),
  ...QA('Kaip suderinti asmeninę dovaną ir mažą biudžetą?','Pirkite vieną jos pomėgį atitinkantį daiktą, o asmeninę dalį paruoškite patys: žinutę, nuotrauką ar konkretų susitikimo planą. Dovanų suma turėtų apimti ir gavimą; nereikia mažo pirkinio paversti brangiu vien dėl dekoracijų.'),
 ],
 'gidai/kaledines-dovanos-mamai':[
  H('Prisiminimų dovana mamai: penki klausimai gerai istorijai'),
  P('Asmenišką albumą ar laišką lengviau paruošti, kai renkate ne bendrus komplimentus, o atpažįstamas akimirkas. Pasirinkite vieną temą: jūsų vaikystės namus, bendrą kelionę, jos išmokytą dalyką ar susitikimų tradiciją. Tokiai dovanai pakanka kelių nuotraukų, jeigu prie kiekvienos yra tikras pasakojimas. Neverta pirkti didžiausio albumo, jei nežinote, kuo jį užpildysite.'),
  L('Kur buvome ir kas tuo metu vyko? Įrašykite vietą bei žinomą datą; jei jos neprisimenate, nespėkite tikslių metų.','Ką mama tada padarė ar pasakė, ką prisimenate iki šiol? Vienas konkretus sakinys stipresnis už bendrą „tu visada rūpinaisi“.','Ką ši akimirka pakeitė jūsų santykyje? Paminėkite tai savo žodžiais, ne sveikinimų šablonu.','Ką šiandien norėtumėte pakartoti? Pasiūlykite vieną susitikimą ar bendrą užsiėmimą.','Kuri istorija skirta tik šeimai? Jos nereikia skelbti viešai vien todėl, kad dovana gražiai atrodo.'),
  H('Rankų liejinys su mama: ką tiksliai dovanosite?'),
  P('Galite įteikti uždarytą rinkinį, suplanuoti jo naudojimą kartu arba dar prieš Kalėdas sukurti liejinį, kurį vėliau užbaigsite. Pirmas variantas palieka mamai daugiau pasirinkimo dėl laiko. Antrasis apima jūsų pačių pagalbą: jūs paruošiate vietą, perskaitote instrukciją ir sutvarkote po veiklos. Trečiasis reikalauja susitikti iš anksto, todėl išskirtinumas slypi bendroje istorijoje, o ne visiškai slaptame rezultate.'),
  P('Poros rinkinys kainuoja 32 €, šeimos – 48 €, balti dažai įeina į abu. Komplektą rinkitės pagal norimą kompoziciją ir konkretaus rinkinio informaciją, ne vien pagal žmonių skaičių nuotraukoje. Poros rinkinio instrukcija ir šeimos rinkinio instrukcija pateikia skirtingus vandens kiekius. Abiejuose receptuose išimtam liejiniui numatytos 5–7 džiovinimo paros prieš dažymą. Jei prieš šventę tiek laiko neliko, įteikite patį rinkinį su kvietimu susitikti vėliau.'),
  H('Kai mamai dovanoja keli suaugę vaikai'),
  P('Pirma sutarkite vieną bendrą mintį, tik tada surinkite pinigus. Vienas žmogus gali pasirūpinti pirkiniu, kitas – nuotraukų atranka, trečias – kelione ar susitikimo derinimu. Prie dovanos pridėkite kiekvieno asmeninį sakinį, kad bendras pirkinys netaptų vien vieno organizatoriaus žinute. Didesnė suma savaime neišsprendžia skirtingų mamos norų ar nepatogios veiklos datos.'),
  P('Pavyzdžiui, galite padovanoti jau pradėtą šeimos prisiminimų albumą ir po švenčių suplanuoti jo peržiūrą. Jūs pasirūpinate nuotraukomis ir užkandžiais, o mama pasirenka, ar norės pridėti savo pasakojimų. Tai darbų pasidalijimo pavyzdys, ne prašymas jai pačiai užbaigti dovaną. Gyvenant skirtinguose miestuose susitikimą galima atskirti nuo siuntos gavimo: svarbu, kad abu dalykai būtų aiškūs.'),
  H('Dažni klausimai apie kalėdinę dovaną mamai'),
  ...QA('Ką dovanoti mamai, kuri sako „nieko nereikia“?','Pasitikslinkite, ar ji nenori naujų daiktų, didelių išlaidų, ar iš tiesų prašo apsieiti be dovanų. Jei ji norėtų daugiau bendro laiko, pasiūlykite vieną konkretų susitikimą ir jo organizavimą prisiimkite patys. Jos atsakymas svarbesnis už bet kurį populiarių dovanų sąrašą.'),
  ...QA('Ar galima dovanoti rankų liejimo rinkinį mamai su suaugusiu vaiku?','Tokią bendro prisiminimo idėją galima svarstyti, jei abu norite dalyvauti. Konkrečiam komplektui ir pasirinktai pozai tinkamumą patikrinkite prieš naudodami medžiagas. Jei mama nenori kūrybinės veiklos, paruoštas albumas ar jūsų laiškas gali būti taiklesnis.'),
  ...QA('Kuo Kalėdų dovana skiriasi nuo dovanos mamai gimtadieniui?','Per Kalėdas dažnai derinate kelių žmonių biudžetą, siuntas ir susitikimus. Gimtadieniui galima susitelkti į vieną jos pačios norą ir atskirą programą. Dovanos mamai gide plačiau aptariame jubiliejų, personalizavimą ir dovanas be progos.'),
 ],
 'gidai/kaledines-dovanos-vyrams':[
  H('Kaip palyginti du pomėgiui skirtus daiktus?'),
  P('Užrašykite, kokį konkretų veiksmą dovana palengvins arba suteiks galimybę išbandyti. Kavinukų atveju tai ruošimo būdas ir gėrimo porcija; žaidimų – dalyvių skaičius, kalba ir žaidimo mechanika; išvykų daiktų – talpa, forma ir tai, ką žmogus jau nešasi. Vien panaši paskirtis nereiškia, kad du daiktai pakeičia vienas kitą. Lyginkite patį naudojimą, o ne didžiausią funkcijų skaičių aprašyme.'),
  L('Žinote tik pomėgį: išsiaiškinkite, kokios dovanos iš tiesų trūksta. Šiame etape dar nepirkite konkretaus modelio.','Žinote norimą kategoriją: patikrinkite turimą įrangą, reikalingus priedus ir gavėjo norą pačiam rinktis.','Žinote tikslų modelį: sutikrinkite visą žymėjimą, komplektaciją ir galutinę pardavėjo sumą. Tik tada spręskite dėl pirkimo.'),
  H('Dovana vyrui, kuris sako, kad viską turi'),
  P('Čia dažnai padeda mažesnis pasirinkimas. Galite pasiūlyti jo jau mėgstamo užsiėmimo vakarą, sunaudojamą jo paties įvardytą produktą arba indėlį į tikslų norimą pirkinį. Pavyzdžiui, kavos mėgėjui gali pakakti jo pasirinktos kavos ir ramaus ryto kartu, o ne naujo prietaiso. Muzikos mėgėjui – kartu sudaryto vakaro iš trijų jau turimų albumų. Žinutėje paaiškinkite, kokį jo įprotį pastebėjote.'),
  P('Jei norite padovanoti veiklą, nuspręskite, kam priklauso jos planavimas. „Padovanojau vakarienę“ ir „parinkau receptą, nupirkau produktus ir pats pagaminsiu“ yra skirtingi pažadai. Vyrui, kuris po darbo norėtų paprasto poilsio, sudėtingas pasiruošimas gali būti netinkama dovanos dalis. Tai išsiaiškinkite anksčiau, negu sumokėsite už nekeičiamos datos užsiėmimą.'),
  H('Asmeninė dovana partneriui: procesas ar rezultatas?'),
  P('Rankų liejimą rinkitės tada, kai abu norite patys kurti bendrą darbą. Poros rinkinyje už 32 € yra vienas alginato pakelis, 1 200 g gipso, kibiras, maišymo pagaliukai ir balti dažai. Iš pradžių pasirenkate patogią rankų padėtį, tada dirbate pagal konkretaus rinkinio instrukciją. Tai bendro dalyvavimo dovana: graži skulptūros iliustracija nepakeičia paties noro įsitraukti.'),
  P('Jei per Kalėdas norite įteikti jau nudažytą darbą, į bendrą planą įtraukite ir džiovinimą. Oficialus poros receptas numato 5–7 paras po liejinio išėmimo. Jeigu ketinate įteikti neatidarytą dėžutę, veiklą galima ramiai suplanuoti po švenčių. Palyginime rankų liejimo rinkinys ar paruošta dovana atskiriame šiuos du formatus.'),
  H('Dažni klausimai apie Kalėdų dovanas vyrams'),
  ...QA('Kaip išrinkti praktišką dovaną nenupirkus dar vieno nenaudojamo daikto?','Paklauskite, kuo jo dabartinis daiktas nepatogus ir ar jis pats nori jį keisti. Jeigu aiškaus atsakymo nėra, verčiau rinktis kitą formatą. Praktiškumą parodo konkretus naudojimas, ne vien gamintojo funkcijų sąrašas.'),
  ...QA('Ar verta pirkti brangesnį pomėgio įrangos modelį staigmenai?','Tik jei žinote norimą tikslų variantą ir suderinamumą. Patyrusiam pomėgio entuziastui pasirinkimo detalės gali būti svarbios, todėl bendras išsirinkimas dažnai saugesnis už spėjimą. Galite išlaikyti staigmeną paruošdami asmeninį kvietimą ir aiškiai įvardytą biudžetą.'),
  ...QA('Ką dovanoti kolegai, palyginti su partneriu ar tėčiu?','Kolegai pirmiausia galioja sutarta suma ir darbo santykis. Partneriui galima remtis bendromis patirtimis, o tėčiui – šeimos istorija ir dabartiniais jo pomėgiais. Todėl kalėdinės dovanos tėčiui turi atskirą pasirinkimo gidą.'),
 ],
 'gidai/kaledines-dovanos-teciui':[
  H('Trys dovanos tėčiui, kurios turi aiškią pradžią'),
  S('Jo pomėgio pirkinys ir pirmas panaudojimas'),
  P('Jei tėtis norėtų išbandyti kitą kavos ruošimo būdą, pirmiausia pasitikrinkite konkretų prietaisą, o prie dovanos pridėkite kavos, jeigu jos reikia, ir pasiūlymą kartu paruošti pirmą puodelį. Jei jis nori knygos, įteikite žinomą leidimą arba palikite galimybę pasirinkti. Toks pirmo panaudojimo sumanymas padeda užbaigti dovaną, tačiau neturėtų virsti pamoka žmogui, kuris pats išmano savo pomėgį.'),
  S('Jo pasakojama šeimos istorija'),
  P('Suraskite tris šeimos nuotraukas ir prie kiekvienos užrašykite tai, ką jau žinote: vietą, žmones ir įvykį. Tuomet pakvieskite tėtį, jei norės, papasakoti, kas liko už kadro. Klausimus paruoškite iš anksto: „Kaip ten nuvykote?“, „Ką tą dieną veikėte?“, „Kas šiame kadre tave labiausiai pralinksmina?“ Gavę jo sutikimą galite pasakojimą įrašyti arba po susitikimo užrašyti ir duoti perskaityti. Dovanos pagrindą paruoškite patys, o pasakojimas tegul lieka kvietimu.'),
  S('Bendra rankų kompozicija'),
  P('Šią kryptį verta rinktis, jei tėčiui artimi apčiuopiami šeimos prisiminimai ir jis pats norėtų dalyvauti. Iš pradžių parodykite veiklos idėją, pasirinkite patogią pozą ir susitarkite, kas ruoš medžiagas. Susikibusių rankų liejinys išsaugo pasirinktą gestą; jis nėra jau pagamintas daiktas, kurį gausite atidarę rinkinio dėžę. Jei per šventę norite įteikti užbaigtą darbą, susitikimą planuokite anksčiau ir laikykitės poros rinkinio instrukcijos arba šeimos rinkinio instrukcijos.'),
  H('Kai dovaną renka keli vaikai: dalykitės ne vien išlaidomis'),
  P('Vienas gali žinoti tėčio pomėgius, kitas turėti nuotraukų, trečias gyventi netoliese ir pasirūpinti susitikimu. Sudėkite šias žinias prieš rinkdami pinigus. Susitarkite, kas bendraus su pardavėju, kas priims siuntą ir kas praneš visiems, kad dovana paruošta. Prie bendro pirkinio pridėkite atskiras trumpas žinutes: taip tėtis matys kiekvieno dėmesį, o ne vien surinktą sumą.'),
  P('Pavyzdžiui, vienas organizatorius nupirks pasirinktą albumą, kiti iki sutartos dienos atsiųs po nuotrauką ir tikrą prisiminimą. Susirinkus įteiksite jau užpildytus pirmus puslapius. Jei kas nors neatsiuntė savo dalies, nesakykite tėčiui, kad dabar jis turės viską surinkti pats. Geriau mažesnė, bet užbaigta dovana nei didelis pažadas be turinio.'),
  H('Kaip išsaugoti staigmeną vis tiek pasitikslinus norą?'),
  P('Klauskite apie naudojimą, o ne apie patį pirkinį: koks dabartinio daikto trūkumas, kokios knygos ieško, kur norėtų nuvažiuoti? Jei atsakymas labai konkretus, užsirašykite tikslų pavadinimą. Jei jis labiau kalba apie norą dažniau susitikti, rinkitės kalendoriuje vietą turinčią veiklą. Staigmena gali likti jūsų parinktas pasakojimas, kortelė ar įteikimas, todėl nereikia rizikuoti nesuderinama įranga vien tam, kad viskas būtų netikėta.'),
  H('Klausimai apie kalėdinę dovaną tėčiui'),
  ...QA('Ką rinktis tėčiui, kuris turi daug įrankių?','Nepradėkite nuo dar vieno universalaus komplekto. Išsiaiškinkite, ar jis pats turi konkretų norimą priedą ir kokio modelio įrangą naudoja. Jei tokio noro nėra, pasiūlykite jo pasirinktą išvyką, knygą arba bendrą susitikimą.'),
  ...QA('Kaip dovanoti bendrą laiką gyvenant kitame mieste?','Pasiūlykite dvi realias atvykimo galimybes ir pasirūpinkite savo kelione. Jei kartu siunčiate daiktą, žinutėje atskirkite jo gavimą nuo susitikimo. Nereikia žadėti vienos datos, kurios dar negalite patvirtinti.'),
  ...QA('Ar prisiminimų dovana turi būti skelbiama viešai?','Ne. Albumas, laiškas, įrašytas pasakojimas ar liejinys gali likti tik šeimai. Nuotraukos ir vaizdo įrašo viešinimą aptarkite atskirai; dalyvavimas dovanos kūrime nėra automatinis sutikimas reklamai.'),
 ],
 'gidai/kaledines-dovanos-tevams':[
  H('Bendras prisiminimas: kaip parodyti abiejų tėvų istoriją?'),
  P('Ruošdami albumą ar kitą atminimo dovaną pradėkite nuo jųdviejų gyvenimo, ne vien nuo vaikų vaikystės. Atrinkite kelionę, kasdienį įprotį, šventę ir bendrą veiklą. Prie vienos nuotraukos galima palikti du skirtingus prisiminimus – žmonės tą pačią akimirką atsimena nevienodai. Jei istoriją dar reikia tikslinti, nekonstruokite tikslių datų iš spėjimo: parašykite tai, ką žinote, o likusius klausimus palikite pokalbiui.'),
  P('Rankų liejimo rinkinys tinka kitokiam prisiminimui, kurį tėvai sukuria dalyvaudami patys. Jei abiem tai malonu, galite pasirūpinti priemonėmis ir darbo vieta. Jei labiausiai džiaugtųsi jau paruoštu rezultatu, daugiau vertės turės jūsų atrinktos nuotraukos ar užbaigtas laiškas. Norintiems palyginti šiuos formatus skirtas gidas rankų liejimo rinkinys ar paruošta dovana.'),
  H('Dovana tėvams per atstumą: trys atskiri susitarimai'),
  L('Kas gaus siuntą? Susitarkite dėl žmogaus ir tinkamos gavimo vietos, kad staigmenos nereikėtų ieškoti nepatogiu adresu.','Kada bus pats įteikimas? Siuntą galima gauti anksčiau, o asmeninę žinutę ar bendrą pokalbį suplanuoti kitu metu.','Kas pasirūpins panaudojimu? Jei dovana reikalauja rezervacijos ar pagalbos, aiškiai pasiūlykite savo dalį; nepalikite viso organizavimo vienam iš tėvų.'),
  P('Gyvenant skirtingose vietose nebūtina visko sutalpinti į Kalėdų dieną. Neatidarytas kūrybinis rinkinys gali tapti kvietimu susitikti vėliau. Jei dovana yra būsima jūsų išvyka kartu, pirmiausia suderinkite kryptį ir judėjimo tempą, o tik tada bilietus. Tas pats principas galioja ir skaitmeniniam čekiui: failą nusiųsti lengva, tačiau dovanos patogumą nulems reali vieta, laikas ir žmonių noras.'),
  H('Kaip susitarti dėl bendros sumos nepaverčiant dovanos varžybomis?'),
  P('Paskelbkite visą galutinę ribą ir palikite indėlį savanorišką. Galima pasiskirstyti ir darbais: vienas užsako, kitas paruošia turinį, trečias padeda įteikti. Pavyzdžiui, trys dovanotojai susitaria dovanai skirti iki 60 €. Jei renkasi poros rinkinį už 32 €, prekei išleidžiama 32 €, o likusi suma nėra privalomas papildomų pirkinių biudžetas. Iš pradžių patikrinkite gavimą ir tikrai reikalingą paruošimą, o nepanaudotus pinigus aptarkite tarpusavyje.'),
  P('Jei vienas tėvų norėtų konkretaus daikto, o kitas – visai kitos veiklos, pasidalykite bendrą sumą pagal abu norus. Dviejų dovanų vertės nebūtina sulyginti iki cento. Svarbiau, kad kiekvienas atpažintų savo pasirinkimą. Kortelėje galima paaiškinti bendrą mintį ir kartu paminėti, kas parinkta kiekvienam atskirai.'),
  H('Dažni klausimai apie bendrą Kalėdų dovaną tėvams'),
  ...QA('Ar buities daiktas gali būti dovana abiem tėvams?','Gali, jei abu patys jo nori ir abu juo naudosis. Jei pirkinys susijęs tik su vieno žmogaus kasdienėmis pareigomis, nevadinkite jo bendra dovana vien dėl to, kad daiktas stovės bendruose namuose.'),
  ...QA('Ką dovanoti, kai vienas tėvų nemėgsta kūrybinės veiklos?','Rinkitės paruoštą prisiminimą arba du atskirus pomėgiams tinkamus pasirinkimus. Kūrybinį rinkinį verta dovanoti tada, kai procesas malonus patiems dalyviams, o ne vien gerai atrodo nuotraukoje.'),
  ...QA('Ar du bilietai arba dvi vietos reiškia visą dovanos kainą?','Ne visada. Atskirai įvertinkite kelionę, pasirinktus papildymus ir registracijos sąlygas. Jei dovanojate tik indėlį, taip ir parašykite, kad gavėjai netikėtai nesužinotų turintys primokėti.'),
 ],
 'gidai/kaledines-dovanos-porai':[
  H('Neatidarytas rinkinys, bendras vakaras ar užbaigta skulptūra?'),
  P('Rankų liejimo idėją porai galima įteikti trimis skirtingais būdais. Neatidaryta dėžutė palieka jiems laisvę pasirinkti dieną. Suplanuotas kūrybos vakaras apima ir jūsų sutartą pagalbą, jeigu pora jos nori. Užbaigta skulptūra reiškia, kad pora jau dalyvavo liejime anksčiau, o dabar gali džiaugtis išdžiovintu ir paruoštu darbu. Šiuos formatus atskirkite dar rinkdamiesi dovaną.'),
  P('Pagal poros rinkinio instrukciją iš formos išimtas liejinys džiovinamas 5–7 paras, kol tampa baltas; dažymas atliekamas po to. Vienos valandos stingimas užpildytoje formoje nėra tas pats, kas galutinis džiovinimas. Jei iki Kalėdų trūksta laiko, dovanokite rinkinį būsimai veiklai, užuot trumpinę recepto etapus. Išėmimo ir džiovinimo gidas padės šiuos laikus atskirti.'),
  H('Pavyzdys: kaip atrodo užbaigta 40 € dovanos mintis?'),
  P('Tarkime, galutinė riba yra 40 €. Poros rinkiniui už 32 € lieka 8 € gavimui ir pasirinktam pakavimui. Tai skaičiavimo pavyzdys, ne pristatymo kainos pasiūlymas. Dovaną gali užbaigti jūsų pačių parašytas kvietimas: kodėl norite išsaugoti šį ryšį ir kada abu galėtumėte tam skirti laiko. Jei faktinė krepšelio suma viršija ribą, paprastinkite pakavimą arba rinkitės kitą idėją, o ne palikite gavėjams netikėtą primokėjimą.'),
  P('Kitokiam poros norui galima pasirinkti žaidimą ir jūsų pasirūpintą pirmą vakarą. Tada vertinkite visą pasirinkto pasiūlymo gavimą ir tai, ar namuose jau nėra tos pačios dėžutės. Šių formatų nereikia matuoti vien daiktų kiekiu: viename kuriamas ilgiau užbaigiamas prisiminimas, kitame – pakartojama veikla. Geresnis yra tas, kurį abu iš tiesų norės naudoti.'),
  H('Dovana pažįstamai porai ir dovana savo partneriui'),
  P('Savo partneriui galite remtis jūsųdviejų pažįstamais įpročiais ir prisiminimais. Kitai porai skirtoje dovanoje svarbiau palikti pasirinkimo: nepriskirkite bendro pomėgio vien todėl, kad vienas žmogus jį paminėjo. Prie kūrybinio rinkinio tinka kvietimas pačiai porai išsirinkti datą ir kompoziciją. Jei dovanojate paslaugą, patikrinkite, ar abiem patogi jos vieta ir numatytas dalyvavimo formatas.'),
  P('Pora, neseniai apsigyvenusi kartu, gali dar rinktis namų stilių. Tokiu atveju didelis dekoratyvus daiktas pagal jūsų skonį ne visada padės. Geriau parodyti idėją, pasiūlyti bendrą veiklą arba leisti pasirinkti iš dviejų jiems tinkamų variantų. Ilgai kartu gyvenančiai porai gali būti svarbesnė konkretaus laikotarpio istorija – kelionė, namai ar atnaujinta sena tradicija.'),
  H('Klausimai apie Kalėdų dovaną porai'),
  ...QA('Ar dovana turi patikti abiem vienodai?','Abu turėtų norėti ja naudotis arba dalyvauti. Nereikia vienodo entuziazmo dėl kiekvienos smulkmenos, tačiau vienas žmogus neturėtų būti įtrauktas tik iš mandagumo. Jei poreikiai labai skiriasi, dvi nedidelės dovanos gali būti taiklesnės.'),
  ...QA('Ką rinktis porai, kuri beveik neturi bendrų laisvų datų?','Venkite iš anksto fiksuoto laiko paslaugų. Galite rinktis jau paruoštą prisiminimą arba priemones, kurias jie panaudos patys pasirinktu metu. Prieš dovanodami kuponą vis tiek patikrinkite galiojimą ir rezervacijos sąlygas.'),
  ...QA('Ar rankų liejimo rinkinys pristatomas su jau pagaminta skulptūra?','Ne. Perkate medžiagas savo darbui sukurti pagal instrukciją. Produkto nuotraukos ir įkvėpimo iliustracijos padeda įsivaizduoti kompoziciją bei apdailą, bet nėra su dėžute pristatomas gatavas liejinys.'),
 ],
 'gidai/kaledines-dovanos-seimai':[
  H('Bendra dovana šeimai, kurioje skiriasi amžius ir pomėgiai'),
  P('Pirmiausia nuspręskite, ar visi turėtų veikti vienu metu. Žaidimui tai gali būti svarbu, o šeimos istorijų albumą galima pildyti per kelis susitikimus. Kūrybinėje veikloje skirtingi žmonės gali pasirinkti skirtingus vaidmenis, tačiau niekas neturėtų privalėti dalyvauti vien dėl bendros dovanos pavadinimo. Jauniausio žmogaus poreikiai ir suaugusiųjų noras padėti yra tokia pati pasirinkimo dalis kaip pati dovanos idėja.'),
  L('Vienas bendras žaidimas: patikrinkite tikrą žaidėjų skaičių, kalbą ir konkretaus leidimo naudojimo nurodymus.','Vienas bendras kūrinys: aptarkite, kas norės prisidėti ir ar rinkinys tinka pasirinktai kompozicijai.','Vienas prisiminimų albumas: paruoškite pradžią ir palikite galimybę prisidėti vėliau, nereikalaudami vienos bendros datos.','Kelios mažos dovanos: pasirinkite po vieną kiekvieno mėgstamą dalyką ir aiškiai parodykite, kam jis skirtas.'),
  H('Rankų liejimo šeimai planas: nuo idėjos iki vietos namuose'),
  P('Prieš užsakydami aptarkite, kieno rankų kompoziciją norite išsaugoti. Tinkamumą lemia ne tik žmonių skaičius, bet ir rankų dydis bei pasirinkta padėtis. Pardavėjui galima aprašyti sumanymą, o gavus rinkinį padėtį išbandyti tuščiame inde. Jei dalyvauja vaikas, pasiruošimą ir eigą prižiūri suaugęs žmogus; nenustatome universalaus amžiaus vien pagal šeimos rinkinio pavadinimą.'),
  P('Šeimos komplektas kainuoja 48 €, jame yra du alginato ir du gipso pakeliai, o balti dažai įtraukti. Savo pasiruošimui naudokitės šeimos rinkinio instrukcija: jos receptas nėra automatiškai padvigubintas poros receptas. Išėmę liejinį numatykite 5–7 džiovinimo paras ir atskirą apdailą. Dar prieš liejimą verta numatyti stabilią vietą, kur darbas galės džiūti ir vėliau stovėti nepasiekiamas atsitiktinio smūgio.'),
  H('Kaip padovanoti ir pirmą panaudojimą?'),
  P('Prie dėžutės pridėkite trumpą pasiūlymą, kokią dalį organizavimo prisiimsite. Žaidimo atveju galite patys iš anksto perskaityti taisykles ir atvykti pirmai partijai. Albumui – surinkti pradines nuotraukas ir užrašyti, kas jose pavaizduota. Kūrybiniam rinkiniui – kartu perskaityti instrukciją, padėti paruošti priemones ir sutvarkyti po veiklos. Pažadas turi atitikti jūsų galimybes, kad dovana neliktų gražia užduotimi užimtiems tėvams.'),
  P('Tarkime, keturi giminaičiai šeimos rinkiniui skiria po 12 €. Susidaro 48 € – tiek kainuoja pats bazinis produktas. Šis pavyzdys dar neapima pristatymo ar pasirinkto pakavimo. Organizatorius turėtų iš anksto patikrinti galutinę sumą ir aptarti, kas padengs papildomą dalį. Toks skaičiavimas padeda išvengti situacijos, kai surinkta suma tiksliai sutampa su prekės kaina, bet trūksta jos gavimui.'),
  H('Klausimai apie kalėdinę dovaną visai šeimai'),
  ...QA('Ar bendra dovana gali pakeisti atskiras dovanas vaikams?','Tai šeimos susitarimas, kurį verta išsiaiškinti prieš perkant. Vien žodis „šeimai“ nepasako, ko tikisi kiekvienas gavėjas. Bendra veikla gali būti pagrindinė dovana arba papildymas, bet neturėtų netikėtai pakeisti jau sutarto individualaus pasirinkimo.'),
  ...QA('Ką rinktis šeimai, kuri gyvena mažame būste?','Išsiaiškinkite, kur dovana bus laikoma ir naudojama. Gali labiau tikti kompaktiškas žaidimas, nedidelė paruošta nuotraukų atranka ar veikla už namų ribų. Kūrybinio rezultato vietą aptarkite prieš pirkdami, nes mažas pradinis rinkinys nereiškia, kad vėliau nereikės vietos darbui.'),
  ...QA('Ar visi turi dalyvauti vienodai?','Ne. Veiklą galima rinktis taip, kad žmonės prisidėtų norimu būdu arba skirtingu laiku. Jei pati veikla įdomi tik vienam, sąžiningiau ją dovanoti jam asmeniškai, o likusiai šeimai parinkti kitą bendrą mintį.'),
 ],
 'gidai/dovanos-moterims':[
  H('Gimtadienis, padėka ar svarbus gyvenimo pokytis?'),
  P('Gimtadienio dovaną galima susieti su jos pačios noru: konkrečiu leidiniu, pomėgio priemone ar seniai aptarta veikla. Padėkai labiau tinka aiškus, proporcingas gestas ir žinutė, už ką dėkojate. Dovana svarbaus pokyčio proga gali pripažinti jos pastangas, tačiau neturėtų nurodinėti, kaip dabar gyventi. Pavyzdžiui, nauji namai savaime nereiškia noro gauti jūsų parinktą didelę dekoraciją, o naujas darbas – poreikio viską sieti su profesija.'),
  P('Jei dovana skirta jubiliejui, iš anksto suderinkite, ar žmogus nori viešo sveikinimo, didelės šventės, ar ramaus susitikimo. Svarbus gimtadienis nesuteikia leidimo rinkti ir skelbti privačias jos nuotraukas. Su kitais dovanotojais geriau pasidalyti vieną patvirtintą mintį ir organizavimo darbus, negu nupirkti kelis tarpusavyje nesusijusius daiktus vien tam, kad bendra suma atrodytų didelė.'),
  H('„Ypatinga“ dovana: parodykite, ką apie žmogų pastebėjote'),
  P('Atsakymą galima užrašyti trimis eilutėmis: „Tu sakei...“, „Todėl parinkau...“, „Mano dalis bus...“. Pavyzdžiui: „Minėjai, kad nori peržiūrėti mūsų kelionės nuotraukas. Paruošiau trumpą jų atranką su datomis. Kitą kartą pasirūpinsiu atspaudais, kuriuos pati išsirinksi.“ Čia dovanos išskirtinumą kuria konkretus prisiminimas ir įvykdomas pasiūlymas. Lygiai taip pat galima paaiškinti knygų kuponą ar bendrą kūrybinį užsiėmimą.'),
  P('Šio principo nereikia paversti ilgu, iškilmingu sveikinimu. Užtenka vieno tikro dalyko, kurį pastebėjote. Jei jis per daug privatus bendrai šventei, žinutę įteikite atskirai. Personalizavimas turėtų būti malonus gavėjai, todėl netikėtai ant gaminio išspausdintas jos portretas ar viešas asmeninės istorijos pasakojimas ne visada yra geriausias sprendimas.'),
  H('Kaip išrinkti bendrą veiklą moteriai, kuri vertina laiką kartu?'),
  P('Palyginkite, kas paruoš priemones ir kas vadovaus veiklai. Užsiėmimas studijoje gali būti patogus, jei norisi mokytojo ir aiškios vietos. Rinkinys namuose suteikia daugiau laisvės dėl dienos, tačiau reiškia savarankišką pasiruošimą. Memocasting poros rinkinys už 32 € leidžia pagal instrukciją kurti rankų liejinį; jis labiausiai tinka tuomet, kai abiem dalyviams įdomus pats procesas. Jei žmogus nori jau užbaigto kūrinio, rinkitės kitą formatą.'),
  P('Bendros veiklos dovaną galite užbaigti pažadu paruošti vietą, iš anksto perskaityti instrukciją ir po susitikimo sutvarkyti. Konkrečią dieną bei palydovą palikite pasirinkti gavėjai. Jei veikla susijusi su nauju pomėgiu, pradžiai paprastai pakanka vienos aiškios patirties; visos įrangos ateities užsiėmimams nereikia pirkti, kol nežinote, ar ji norės tęsti.'),
  H('Trumpi atsakymai renkant dovaną moteriai'),
  ...QA('Ką dovanoti moteriai, kuri turi aiškų skonį?','Remkitės jos konkrečiu noru arba leiskite pačiai pasirinkti kategorijos viduje. Dydis, modelis, medžiaga ar spalva gali būti svarbūs, todėl vien artima nuojauta nepakeičia tikslaus pasirinkimo. Jūsų dėmesį parodys ir tai, kad prisiminėte jos išsakytą norą.'),
  ...QA('Kaip išvengti dovanos, kuri skamba kaip pastaba?','Nedovanokite neprašytų priemonių tariamam trūkumui taisyti. Pirmiausia patikrinkite, ar tokį norą išsakė pati gavėja. Jos mėgstamas užsiėmimas arba aiškiai parinkta bendra patirtis yra geresnis atspirties taškas negu jūsų sumanytas „naudingas pasikeitimas“.'),
  ...QA('Ar reikia atskiros dovanos kiekvienai progai?','Dovanos mintį verta susieti su proga, tačiau nebūtina kaskart pirkti naujos rūšies daiktą. Tęsiamas pomėgis, naujas bendros istorijos skyrius ar suderintas susitikimas gali būti prasmingas ir kitą kartą. Kalėdinės dovanos moterims atskirai apima sezono biudžetą ir pasiruošimą.'),
 ],
 'gidai/dovanos-mamai':[
  H('Kaip paruošti dovaną mamai, kurią ji galės iš karto atpažinti?'),
  P('Išsirinkite vieną pasakojimo kryptį: namus, kuriuose užaugote, jos pamėgtas keliones, kartu gamintą patiekalą ar tradiciją, kurią norite tęsti. Surinkite turimą medžiagą ir paruoškite mažą užbaigtą dalį. Tai gali būti keturi albumo puslapiai, vienas tikras receptas su jūsų prisiminimu arba laiškas apie konkretų jos išmokytą dalyką. Tokia dovana neatrodo anoniminė net ir be vardo ant pakuotės.'),
  P('Pavyzdžiui, norite priminti bendrą išvyką. Atrinkite penkias nuotraukas: kelionės pradžią, vietą, netikėtą įvykį, jūsųdviejų kadrą ir vieną mažą detalę. Prie kiekvienos parašykite po sakinį savo žodžiais. Jei norisi pridėti dar vieną susitikimą, pasiūlykite panašią vietą arba tos dienos patiekalą, kurį pagaminsite patys. Tai redakcinis dovanos paruošimo pavyzdys, o ne tikro kliento istorija.'),
  H('Mamos jubiliejus: darbų planas keliems dovanotojams'),
  L('Prieš perkant: sužinokite, kaip pati mama norėtų pažymėti progą, ir sutarkite galutinę bendrą sumą.','Turinys: kiekvienas paruošia vieną konkretų prisiminimą, o vienas žmogus sujungia juos į vientisą dovaną.','Pirkimas: vienas organizatorius patikrina gaminį ar paslaugą, užsako ir išsaugo visą informaciją.','Įteikimas: iš anksto nuspręskite, kas kalbės, kiek laiko užims sveikinimas ir ar privati dalis bus įteikta atskirai.','Po šventės: jei dovana yra veikla, padėkite susitarti dėl tikros datos; nepalikite vien čekio ar pažado.'),
  P('Šis pasidalijimas tinka ir mažai šeimai: vienas žmogus gali atlikti kelias dalis. Svarbiausia, kad mama netaptų savo dovanos renginio organizatore. Jei norite paruošti didesnį prisiminimų darbą, rinkite tik medžiagą, kurią žmonės sutinka naudoti, ir aiškiai skirkite tai, kas bus rodoma visiems, nuo to, kas liks vien jai.'),
  H('Kūrybinė dovana mamai: trys skirtingi galutiniai rezultatai'),
  P('Pirmasis – priemonių rinkinys, kurį mama naudos pasirinktu metu. Antrasis – jūsųdviejų susitikimas ir bendra veikla. Trečiasis – jūsų iš anksto užbaigtas kūrinys. Jei svarstote rankų liejimą, šiuos variantus ypač svarbu atskirti: dėžutėje yra medžiagos, o ne gatava skulptūra. Norint išsaugoti pačios mamos rankų kompoziciją, jos dalyvavimo suplanuoti visiškai slapta nepavyks.'),
  P('Pagal poros ir šeimos rinkinių instrukcijas išimtas liejinys dar džiovinamas 5–7 paras prieš dažymą. Jei dovanos reikia jau artėjančią dieną, įteikite neatidarytą rinkinį ir sutarkite dėl veiklos vėliau. Jei turite laiko iš anksto susitikti, užbaigtą darbą galima įteikti su jūsųdviejų nuotrauka ar kortele, primenančia kūrimo dieną. Tikslius naudojimo žingsnius pateikia poros rinkinio instrukcija ir šeimos rinkinio instrukcija.'),
  H('Klausimai apie asmenines dovanas mamai'),
  ...QA('Ką dovanoti mamai be progos?','Pasirinkite nedidelį konkretų dėmesį, kurį ji norėtų priimti: jau paruoštą laišką, jos mėgstamą daiktą ar suderintą susitikimą. Nereikia didelio pirkinio vien tam, kad būtų aišku, jog dovana nuoširdi. Dažnai daugiau pasako jūsų atliktas paruošimas.'),
  ...QA('Ar personalizuota dovana būtinai turi būti su vardu?','Ne. Jūsų atrinktos nuotraukos, parašytas pasakojimas ar kartu sukurtas darbas jau gali būti asmeniški. Jei vis dėlto užsakote užrašą ar graviravimą, sutikrinkite tikslų tekstą ir maketą prieš gamybą.'),
  ...QA('Kaip dovanoti mamai, kuri retai prašo ko nors sau?','Pasiūlykite du aiškius variantus ir išklausykite atsakymą. Galite paklausti, ar ji norėtų susitikimo, priemonės pomėgiui ar ramiai paruošto prisiminimo. Nereikia automatiškai rinktis buities arba vaiko priežiūros daikto, jei dovana skirta jai pačiai.'),
 ],
};

const replacements={
 'gidai/dovana-porai':[
  P('Dovaną porai pradėkite nuo vieno klausimo: ką abu žmonės norėtų gauti – jau paruoštą daiktą, priemones kūrybai ar progą kartu ką nors patirti? Rankų liejimo rinkinys tinka norintiems patiems sukurti bendrą prisiminimą. Kitu atveju taiklesnis gali būti paruoštas albumas, abiejų norimas daiktas arba jiems patogi išvyka. Šiame gide palyginsite formatus, pasiruošimą ir tai, ką iš tikrųjų įteiksite per progą.'),
  L('Norite padovanoti bendrą kūrybą → rinkitės priemones ir palikite porai galimybę pasirinkti laiką.','Norite įteikti užbaigtą prisiminimą → pasirūpinkite turiniu ir paruošimu iki susitikimo.','Norite padovanoti išvyką → patikrinkite visą dviejų žmonių dalyvavimą, vietą ir datos lankstumą.'),
  H('Trys dovanos formatai: kuo jie skiriasi porai?'),
  S('Rinkinys, su kuriuo pora kurs pati'),
  P('Įteikiate priemones ir aiškią idėją. Gavėjai pasirenka, kada imtis veiklos ir kaip atrodys jų darbas. Pagrindinis privalumas – jų pačių dalyvavimas; svarbi sąlyga – abu turi norėti kurti. Jei vienas žmogus mėgsta rankdarbius, o kitas tam visiškai abejingas, vien užrašas „porai“ šio skirtumo neišspręs.'),
  S('Paruoštas asmeninis prisiminimas'),
  P('Įteikiate jau užpildytą albumą, atrinktų nuotraukų pasakojimą ar kitą iš anksto užbaigtą darbą. Porai nebereikia planuoti bendros kūrimo datos, tačiau jūs turite pažinoti jų istoriją ir turėti tinkamos medžiagos. Tuščias albumas ir jūsų paruoštas albumas yra skirtingos dovanos; tai sąžiningai parodykite įteikdami.'),
  S('Bendra veikla ar išvyka'),
  P('Svarbiausi du dalyviai, vieta, kelionė ir galimos datos. Dovanodami čekį patikrinkite, ar pasiūlymas apima abu žmones, kaip registruojamasi ir kas kainuoja papildomai. Lankstus kvietimas geresnis už netinkamą fiksuotą datą, jeigu abiejų planų nežinote. Čekio įsigijimas pats savaime dar nėra rezervuota vieta.'),
  H('Rankų liejimo rinkinys porai: ką gaunate už 32 €?'),
  P('Memocasting poros rinkinio bazinė kaina – 32 €. Jame yra vienas alginato pakelis, 1 200 g gipso, kibiras, maišymo pagaliukai ir balti dažai. Alginatu suformuojamas rankų atspaudas, o gipsu užpildoma likusi forma. Tikslią darbo eigą rinkitės pagal savo komplekto instrukciją; produkto iliustracijos padeda įsivaizduoti kompoziciją, bet dėžutėje nėra jau paruoštos skulptūros.'),
  P('Dovaną galima pritaikyti be papildomų dekoratyvių pirkinių. Pridėkite vieną žinutę, kokį ryšį norite išsaugoti, ir pasiūlymą ramiai išsirinkti kūrimo dieną. Jei renkate dovaną savo partneriui, galite pasiūlyti pasirūpinti priemonėmis ir vieta. Dovanodami kitai porai palikite jos nariams spręsti, ar jie nori pagalbos, ar mieliau viską atliks dviese.'),
  H('Kaip gimsta rankų liejinys ir kiek etapų reikės suplanuoti?'),
  L('Pasiruošimas: perskaitote instrukciją, susidedate priemones ir tuščiame inde išbandote patogią rankų padėtį.','Atspaudas: pagal instrukciją sumaišote alginatą su vandeniu ir suformuojate pasirinktą rankų kompoziciją.','Liejimas: ištraukus rankas lieka ertmė; ją užpildote atskirai paruoštu gipso mišiniu.','Išėmimas: laikotės konkrečiame recepte numatyto stingimo ir formos pašalinimo žingsnių.','Užbaigimas: liejinį nuvalote, išdžiovinate ir tik po to dažote. Visi šie etapai nėra vienas trumpas vakaro veiksmas.'),
  P('Poros rinkinio instrukcijoje numatyta užpildytą formą palikti vienai valandai, o išimtą liejinį džiovinti 5–7 paras, kol jis taps baltas. Išėmimo laikas nėra paruošimo dažymui laikas. Jei norite per metines ar gimtadienį įteikti jau užbaigtą skulptūrą, susitikimą kūrimui suplanuokite anksčiau; jei įteikiate patį rinkinį, veiklą galima pasirinkti vėliau.'),
  H('Kada ši dovana porai tinka geriausiai?'),
  P('Ji gali tikti metinėms, įkurtuvėms ar kitai porai prasmingai progai, kai abu norėtų savo rankomis sukurti prisiminimą. Progos pavadinimas čia nėra svarbesnis už patį norą. Jei pora mėgsta planuoti ramius vakarus namuose, rinkinys gali pratęsti tą įprotį. Jei abu nemėgsta kūrybinio pasiruošimo, geriau paruoštas daiktas arba jų pasirinkta paslauga.'),
  P('Metinėms svarbų bendrą įvykį galima priminti trumpa kortele: namų pradžia, pirmoji kelionė ar jūsų tradicija. Vestuvių dovanos atveju verta vengti privalomos papildomos programos per pačią šventę. Tegu jaunavedžiai pasirenka, ar kurti po jos, ar apskritai norėtų tokios veiklos. Konkrečiai datos planavimą aptaria dovana vestuvių metinėms, o šventinį dviejų žmonių biudžetą – kalėdinės dovanos porai.'),
  H('Kaip suskaičiuoti visą dovanos kainą?'),
  P('Palyginkite bazinę prekę, pasirinktas priemokas, pristatymą ir savo pasirinktą pakavimą. Pavyzdžiui, jei bendra riba yra 45 €, poros rinkiniui už 32 € lieka 13 € kitoms išlaidoms. Tai tik biudžeto likutis, o ne siuntimo tarifas. Balti dažai jau įeina, todėl jų nereikia skaičiuoti kaip privalomo papildomo pirkinio. Kitas spalvas ir faktinę galutinę sumą tikrinkite produkto puslapyje bei krepšelyje.'),
  P('Lyginant su paruoštu individualiu kūriniu svarbi ir kita išlaidų paskirtis: rinkinys apima medžiagas jūsų darbui, o gatavo kūrinio kaina gali apimti autoriaus gamybą ir apdailą. Abu formatai vertingi skirtingam poreikiui. Rinkinys ar paruošta dovana padės apsispręsti, ar norite dovanoti dalyvavimą, ar užbaigtą rezultatą.'),
  H('Įteikimo idėja, kuri palieka porai laisvės'),
  P('Galite parašyti: „Norėjau padovanoti progą sukurti jūsų bendrą prisiminimą. Išsirinkite dieną, kurią norėtumėte tam skirti laiko.“ Tai žinutės pavyzdys, kurį verta perrašyti pagal savo santykį. Jei siūlote pagalbą, konkrečiai įvardykite, ką atliksite, ir neįrašykite veiklos datos jos nesuderinę.'),
  P('Neatidarytą rinkinį pakuokite taip, kad būtų išsaugotos jo medžiagos ir instrukcija. Jei įteikiate jau užbaigtą liejinį, pasirūpinkite stabilumu, apsauga nuo judėjimo ir smulkių dalių pažeidimo. Baigtam darbui numatykite sausą stabilią vietą namuose. Medinis padėklas šiuo metu išparduotas; kompozicijos nuotrauka nereiškia, kad toks priedas pristatomas kartu.'),
  H('Dažnai užduodami klausimai apie dovaną porai'),
  ...QA('Ar rinkinį galima dovanoti visai nebandžiusiems rankų liejimo?','Galima svarstyti kaip pirmą kūrybinę veiklą, jei gavėjai nori įsitraukti ir pasiruoš skaitydami instrukciją. Nepriekaištingo rezultato iš anksto nežadame: jam svarbi pasirinkta poza, medžiagų paruošimas ir darbo eiga. Neaiškų žingsnį pasitikslinkite prieš pradėdami.'),
  ...QA('Ar reikia pirkti baltus dažus atskirai?','Ne, balti dažai į poros rinkinį įtraukti. Jie naudojami išdžiovintam liejiniui pagal instrukciją. Kitų spalvų prieinamumą ir galimas priemokas matysite pasirinkdami prekę.'),
  ...QA('Ar galėsime tą pačią dieną įteikti nudažytą liejinį?','To neplanuokite pagal poros receptą: po išėmimo numatytos 5–7 džiovinimo paros prieš dažymą. Tą dieną galima įteikti rinkinį arba pradėti kūrimą, tačiau tai kitas dovanos formatas.'),
  ...QA('Ką daryti, jei neaišku, ar pora norėtų kurti?','Pasiūlykite dvi skirtingas kryptis – kūrybinę veiklą arba paruoštą prisiminimą – ir išklausykite abiejų. Jei bendro noro nėra, rinkitės kitą formatą. Dovanotojo susižavėjimas idėja neturėtų virsti gavėjų pareiga.'),
  P('Komplektaciją ir recepto etapus sutikrinome su Memocasting produktų informacija bei originaliomis poros ir šeimos instrukcijomis 2026 m. spalio 26 d. Tai mūsų parduodamas rinkinys; įteikimo situacijos yra redakciniai pavyzdžiai, o iliustracijos nėra konkrečių klientų darbų įrodymas.'),
 ],
 'gidai/dovana-seimai':[
  P('Gera dovana šeimai turi aiškiai įtraukti tuos žmones, kuriems ją dovanojate. Vieniems tiks bendra kūryba, kitiems – žaidimas, išvyka arba jūsų paruoštas prisiminimas. Pradėkite nuo žmonių ir jų noro dalyvauti, o tada palyginkite pasiruošimą bei visos grupės išlaidas. Šis gidas padės išrinkti bendrą dovaną, kuri bus panaudota ir nepaliks vienam šeimos nariui viso organizavimo.'),
  L('Norintiems kurti patiems – priemonės ir pagal jų naudojimo sąlygas suplanuota veikla.','Norintiems bendrauti be ilgo pasiruošimo – tinkamo dalyvių skaičiaus žaidimas arba jūsų organizuojamas susitikimas.','Norintiems išsaugoti istoriją – jau pradėtas albumas, laiškų rinkinys ar kitas užbaigtas prisiminimas.'),
  H('Pirmiausia apibrėžkite, kam iš tiesų skirta dovana'),
  P('Žodis „šeima“ gali reikšti porą, tėvus su vaikais, kelias kartas arba atskirai gyvenančius artimuosius. Kiekvienai grupei skirsis laikas, naudojimo vieta ir galimybė susitikti. Paklauskite, kas iš tikrųjų norėtų prisidėti ir kas būtų nepatogu: kelionė, fiksuota data, triukšminga vieta, sudėtingos taisyklės ar ilgas kūrybinis procesas. Į šiuos atsakymus verta atsižvelgti prieš pasirenkant prekę.'),
  P('Galite paklausti taip: „Norėčiau padovanoti kažką bendro. Labiau norėtumėte kurti namuose, kartu išvykti ar turėti jau paruoštą šeimos prisiminimą?“ Klausimas palieka pasirinkimą, bet dar neatskleidžia konkrečios dovanos. Jei girdite skirtingus norus, bendrumą galima kurti keliomis mažomis dalimis, o ne ieškoti vieno visiems privalomo užsiėmimo.'),
  H('Keturi šeimos dovanos formatai ir jų skirtumai'),
  S('Kūrybinė veikla namuose'),
  P('Tinka, kai patinka pats kūrimas ir galima pasiruošti vietą. Įvertinkite priemones, konkretaus rinkinio naudojimo nurodymus ir tai, kas padės dalyviams. Dovanotojas gali pasirūpinti pasiruošimu bei sutvarkymu, jei šeima to nori. Toks formatas palieka daugiau laisvės dėl datos, tačiau darbas nenutinka savaime vien atidarius dėžę.'),
  S('Žaidimas ir kartu praleistas vakaras'),
  P('Čia svarbūs tikras žaidėjų skaičius, leidimo kalba, taisyklių pobūdis ir konkretaus gamintojo naudojimo informacija. Bendradarbiavimo bei varžymosi žaidimai kuria skirtingą vakarą. Jei šeima anksčiau nežaidė, padovanokite ir paprastą pradžią: iš anksto susipažinkite su taisyklėmis ir pasiūlykite vieną bandomąją partiją, o ne privalomą ilgą turnyrą.'),
  S('Išvyka ar vedamas užsiėmimas'),
  P('Palyginkite kainą visiems numatytiems dalyviams, o ne mažiausią skelbiamą vieno bilieto sumą. Reikės laiko, kelionės, galbūt rezervacijos ir papildomų išlaidų. Jei gyvenate skirtinguose miestuose, pirmiausia sutarkite, kur būtų patogu susitikti. Elektroninis čekis išsprendžia jo persiuntimą, bet ne šiuos dalyvavimo klausimus.'),
  S('Jūsų paruoštas šeimos prisiminimas'),
  P('Albumą, trumpą nuotraukų istoriją ar artimųjų laiškus galima įteikti jau užbaigtus. Paruoškite turinį patys ir palikite laisvę prisidėti ateityje. Nenaudokite privačių nuotraukų ar pasakojimų viešai be atskiro susitarimo. Jei šeimai nepatinka nauji namų daiktai, tą pačią istoriją galima pateikti jų pasirinktu skaitmeniniu būdu, prieš tai suderinus prieigą.'),
  H('Šeimos rankų liejimo rinkinys: ką verta žinoti?'),
  P('Memocasting šeimos rinkinio bazinė kaina – 48 €. Jame yra du alginato ir du gipso pakeliai; balti dažai įtraukti. Rinkiniu patys kuriate savo rankų kompoziciją: alginate suformuojamas atspaudas, o į likusią ertmę pilamas paruoštas gipsas. Produkto nuotraukos ir iliustracijos padeda įsivaizduoti rezultatą, tačiau pats perkamas produktas yra medžiagų komplektas.'),
  P('Prieš pirkdami aptarkite konkrečią norimą rankų padėtį ir dalyvius. Rankų dydžiai bei poza svarbūs, todėl neteigiame, kad į vieną rinkinį vienodai tiks bet kokia grupė. Gavę rinkinį pozą išbandykite tuščiame inde. Jei dalyvauja vaikas, reikalinga suaugusiojo priežiūra ir konkrečių naudojimo nurodymų laikymasis; bendras pavadinimas nenustato universalaus tinkamo amžiaus.'),
  H('Kaip šeimai suplanuoti kūrimą ir užbaigimą?'),
  P('Atskirkite pasiruošimą, atspaudo formavimą, gipso liejimą, išėmimą ir apdailą. Šeimos rinkinio instrukcija nurodo konkrečius kiekius bei temperatūras, todėl poros recepto automatiškai nedvigubinkite. Abu originalūs receptai numato išimtą liejinį džiovinti 5–7 paras, kol jis taps baltas, ir tik tada dažyti. Džiovinimas gali tęstis po bendro susitikimo, todėl iš anksto susitarkite, kas tuo etapu pasirūpins darbu.'),
  P('Pavyzdžiui, vienas žmogus pasirūpina darbo vieta ir perskaito visą instrukciją, dalyviai pasirenka patogią pozą, o po išėmimo sutariama, kur darbas džiūs ir kas vėliau jį užbaigs. Tai vaidmenų pasidalijimo pavyzdys, ne universali grupės sudėtis. Jei tokia veikla šeimai neatrodo maloni, paruoštas albumas arba paprastesnis bendras susitikimas gali būti geresnė dovana.'),
  H('Bendros dovanos biudžetas: kas į jį įeina?'),
  P('Susumuokite prekę ar dalyvių bilietus, pristatymą, kelionę, būtinus papildymus ir pasirinktą pakavimą. Pavyzdžiui, turint 60 € bendrą ribą ir pasirinkus šeimos rinkinį už 48 €, liktų 12 € kitoms išlaidoms. Tai biudžeto pavyzdys, ne siuntimo pasiūlymas. Jei dovanai skiria keli giminaičiai, sutarkite visą ribą ir atsakingą organizatorių, o ne vien vienodą kiekvieno įnašą.'),
  P('Ne visą likutį būtina išleisti papildomiems daiktams. Jūsų paruošta nuotrauka, trumpa kortelė ir konkretus pagalbos pasiūlymas gali užbaigti mintį. Jei tiksli galutinė suma netelpa į ribą, pakeiskite dovanos formatą arba apimtį. Netikėtas prašymas gavėjams primokėti neturėtų tapti paskutine dovanos dalimi.'),
  H('Prie dovanos pridėkite pirmo panaudojimo planą'),
  L('Įvardykite vieną veiklą, kurią šeima pati pasirinko.','Pasiūlykite laiką arba kelias galimybes, bet galutinę datą suderinkite.','Parašykite, kokią pasiruošimo dalį prisiimsite jūs.','Paaiškinkite, ką gavėjai jau turi ir ko dar reikės pagal konkrečios dovanos sąlygas.','Palikite galimybę pakeisti sumanymą, jei dalyvauti nebenorima ar pasikeičia planai.'),
  H('Dažnai užduodami klausimai apie dovaną šeimai'),
  ...QA('Ar visiems reikia dalyvauti vienoje veikloje?','Ne. Galima rinktis skirtingus norimus vaidmenis arba prisidėti kitu metu. Jei pati veikla domina tik vieną žmogų, jos neverta pristatyti kaip dovanos visai šeimai. Bendras pasirinkimas turėtų būti aptartas, o ne nuleistas iš viršaus.'),
  ...QA('Kaip pasirinkti dovaną šeimai su vaikais?','Remkitės konkrečios prekės amžiaus bei naudojimo nurodymais ir suaugusiųjų galimybe padėti. Taip pat svarbūs vaikų pomėgiai, veiklos vieta ir laikas. Iš bendros šeimos rinkinio nuotraukos nespręskite apie medžiagų tinkamumą kiekvienam vaikui.'),
  ...QA('Kuo skiriasi poros ir šeimos rankų liejimo rinkiniai?','Skiriasi jų komplektacija ir receptai. Poros rinkinys kainuoja 32 €, šeimos – 48 €, balti dažai įeina į abu. Rinkitės pagal konkrečią norimą kompoziciją ir produkto informaciją; neperkeldami vieno rinkinio vandens kiekių į kitą.'),
  ...QA('Ką rinktis, jei šeimai sunku susitikti vienu metu?','Tinka jau paruoštas prisiminimas arba dovana, prie kurios galima grįžti skirtingomis dienomis. Jei renkatės bendrą veiklą, pirmiausia suderinkite realią galimybę susitikti ir nepirkite nekeičiamos datos vien tikėdamiesi, kad visi prisitaikys.'),
  P('Memocasting komplektaciją ir originalių instrukcijų etapus sutikrinome 2026 m. spalio 26 d. Mūsų rinkiniai šiame gide pristatomi kaip vienas iš šeimai skirtų formatų. Darbų pasidalijimo ir biudžeto situacijos yra redakciniai pavyzdžiai, ne realių klientų atsiliepimai ar atlikti produktų bandymai.'),
 ],
};

export function editorialDepthChanges(pkg){
 const pages=new Map(pkg.pages.map(p=>[p.slug,p]));
 return Object.keys(guideBriefs).map(slug=>{
  const old=pages.get(slug);assert.ok(old,slug);
  const body=structuredClone(replacements[slug]||old.body);
  if(!replacements[slug]){
   // Replace overlapping old sections rather than padding the article twice.
   const superseded={
    'gidai/kaledines-dovanos-teciui':['Dovanų idėjos pagal tai, ką apie jį žinote'],
    'gidai/kaledines-dovanos-vyrams':['Ką rinktis turinčiam viską?'],
    'gidai/kaledines-dovanos-mamai':['Ką rinktis mamai, kuri sako, kad nieko nereikia?'],
    'gidai/dovanos-moterims':['Kaip progą panaudoti prasmingai?'],
   };
   for(const heading of superseded[slug]||[]){const start=body.findIndex(b=>b.type==='heading'&&b.text===heading);assert.ok(start>=0,heading);const next=body.findIndex((b,i)=>i>start&&b.type==='heading'&&b.level===2);body.splice(start,(next<0?body.length:next)-start);}
   const extra=additions[slug];assert.ok(extra?.length,'Missing final content: '+slug);
   const sourceNote=body.findIndex((b,i)=>i>body.length-5&&b.type==='paragraph'&&/tikrin|tikrint/.test(b.text)&&/2026/.test(b.text));
   const position=sourceNote>0&&body[sourceNote-1].type==='heading'&&/atrink|šaltin/i.test(body[sourceNote-1].text)?sourceNote-1:sourceNote;
   body.splice(position<0?body.length:position,0,...structuredClone(extra));
  }
  const text=body.map(b=>b.text||b.items?.join(' ')||'').join(' ');
  const links=structuredClone(replacements[slug]?[]:old.links);
  const candidates=[
   ['rinkinys-porai','poros rinkinio'],
   ['seimos-rinkinys','šeimos rinkinio'],
   ['instrukcijos/poros-rinkiniui','poros rinkinio instrukcija'],
   ['instrukcijos/poros-rinkiniui','poros rinkinio instrukciją'],
   ['instrukcijos/poros-rinkiniui','poros rinkinio instrukcijoje'],
   ['instrukcijos/seimos-rinkiniui','šeimos rinkinio instrukcija'],
   ['instrukcijos/seimos-rinkiniui','šeimos rinkinio instrukcijos'],
   ['gidai/dziovinimas-ir-isemimas','Išėmimo ir džiovinimo gidas'],
   ['gidai/ranku-liejimo-rinkinys-ar-paruosta-dovana','rankų liejimo rinkinys ar paruošta dovana'],
   ['gidai/ranku-liejimo-rinkinys-ar-paruosta-dovana','Rinkinys ar paruošta dovana'],
   ['gidai/dovana-vestuviu-metinems','dovana vestuvių metinėms'],
   ['gidai/kaledines-dovanos-porai','kalėdinės dovanos porai'],
   ['gidai/kaledines-dovanos-teciui','kalėdinės dovanos tėčiui'],
   ['gidai/kaledines-dovanos-moterims','Kalėdinės dovanos moterims'],
   ['gidai/dovanos-mamai','Dovanos mamai'],
  ];
  for(const[target,label]of candidates){const p=pages.get(target);assert.ok(p,target);if(p.id!==old.id&&text.toLocaleLowerCase('lt').includes(label.toLocaleLowerCase('lt'))&&!links.some(l=>l.targetPageId===p.id&&l.label.toLocaleLowerCase('lt')===label.toLocaleLowerCase('lt')))links.push({targetPageId:p.id,label});}
  const seen=new Set(),uniqueLinks=links.filter(l=>{const key=l.targetPageId+':'+l.label.toLocaleLowerCase('lt');if(seen.has(key))return false;seen.add(key);return true;});
  assert.ok(body.length<=100,slug+' block limit');assert.ok(uniqueLinks.length<=30,slug+' link limit');
  return{slug,id:old.id,expectedRevisionHash:old.revisionHash,question:guideBriefs[slug],input:{body,links:uniqueLinks}};
 });
}
